    "id": "java-exceptions-hierarchy-handling",
    "title": "Exceptions I: The Throwable Hierarchy, Checked vs Unchecked & Multi-Catch",
    "slug": "java-exceptions-hierarchy-handling",
    "track": "java-foundations",
    "category": "Java Foundations",
    "subCategory": "Exception Safety & Handling",
