    "id": "java-exceptions-chaining-custom",
    "title": "Exceptions III: Exception Chaining, Custom Exceptions & Translation",
    "slug": "java-exceptions-chaining-custom",
    "track": "java-foundations",
    "category": "Java Foundations",
    "subCategory": "Exception Safety & Handling",
    "language": "Java",
