    "id": "java-concurrency-executors-atomic-locks",
    "title": "Concurrency III: ReentrantLock, Executor Pools, ForkJoin & Atomic CAS",
    "slug": "java-concurrency-executors-atomic-locks",
    "track": "java-foundations",
